import torch


def run(x, p):
    return x.mvlgamma_(p)


def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    dtype = ctx["x__dtype"]
    if isinstance(dtype, str):
        dtype = getattr(torch, dtype.replace("torch.", ""))
    p = ctx["p"]
    torch.manual_seed(42)
    x = torch.rand(shape, dtype=dtype, device=device)
    x = x + (p - 1) / 2 + 1.0
    return {"x": x}
